window.__CONTENT_EN__=window.__CONTENT_EN__||{};window.__CONTENT_EN__[54]={"5400":{"example:5400:exzh":"He is a famous poet.","example:5400:exzh2":"I like reading a poet's works.","example:5400:exzh3":"There are many poets in Japan.","example:5400:exzh4":"She is a poet with great sensitivity.","example:5400:exzh5":"Poets get inspiration from nature."},"5401":{"example:5401:exzh":"This project needs a special fund.","example:5401:exzh2":"I set up a new fund.","example:5401:exzh3":"Donated money goes into the fund.","example:5401:exzh4":"I want to learn about how funds are managed.","example:5401:exzh5":"We're raising money for a foreign-policy fund."},"5402":{"example:5402:exzh":"I like watching movies on the screen.","example:5402:exzh2":"This screen is really big.","example:5402:exzh3":"I bought a new screen.","example:5402:exzh4":"The screen needs cleaning.","example:5402:exzh5":"This movie was shown on the screen."},"5403":{"example:5403:exzh":"I like Chinese food.","example:5403:exzh2":"I had dinner in Chinatown.","example:5403:exzh3":"I'm interested in Chinese culture.","example:5403:exzh4":"Of all Asian cuisines, I like Chinese food best.","example:5403:exzh5":"There are many kinds of Chinese food."},"5404":{"example:5404:exzh":"When we took the photo, everyone did a peace sign.","example:5404:exzh2":"I just can't find the last piece of the puzzle.","example:5404:exzh3":"At the end of the concert, the singer shouted 「love and peace」.","example:5404:exzh4":"This cake is four hundred yen a piece.","example:5404:exzh5":"At the anti-war march, placards reading 「peace」 stood out."},"5406":{"example:5406:exzh":"He hates tormenting animals.","example:5406:exzh2":"In this movie there's a scene where the main character is tormented.","example:5406:exzh3":"She said she wants to stop tormenting herself.","example:5406:exzh4":"I went on a trip to heal my battered heart.","example:5406:exzh5":"Hurting other people is never acceptable."},"5407":{"example:5407:exzh":"I ended up inviting him against his will.","example:5407:exzh2":"I'm being forced to work.","example:5407:exzh3":"I did what I was forced to do.","example:5407:exzh4":"Forcing someone to study isn't good.","example:5407:exzh5":"He was dragged away by force."},"5408":{"example:5408:exzh":"He goes to school every day.","example:5408:exzh2":"I made friends at school.","example:5408:exzh3":"A new school opened.","example:5408:exzh4":"I like going to school.","example:5408:exzh5":"This school puts special emphasis on English classes.","grammar:5408:ex:trans":"He goes to school every day.","grammar:5408:ex:structure":"彼は＋毎日＋学校に通っています","grammar:5408:ex:explain":"「学校」 is the most basic word for a school and can refer to the place where classes are held in general. This sentence uses 「学校に通う」, which means going to school regularly, not just once on a particular day. Combined with 「毎日」, it naturally means going to school every day.","grammar:5408:ex:words:0:zh":"he","grammar:5408:ex:words:0:note":"かれ","grammar:5408:ex:words:0:pos":"pronoun","grammar:5408:ex:words:1:zh":"marks the topic","grammar:5408:ex:words:1:pos":"particle","grammar:5408:ex:words:2:zh":"every day","grammar:5408:ex:words:2:note":"まいにち","grammar:5408:ex:words:2:pos":"noun","grammar:5408:ex:words:3:zh":"school","grammar:5408:ex:words:3:note":"がっこう","grammar:5408:ex:words:3:pos":"noun","grammar:5408:ex:words:4:zh":"to, toward","grammar:5408:ex:words:4:pos":"particle","grammar:5408:ex:words:5:zh":"commuting (to work or school)","grammar:5408:ex:words:5:note":"かよっています；the polite ている form of 「通う」","grammar:5408:ex:words:5:pos":"verb","grammar:5408:ex:points:0":"「学校」 is read 「がっこう」; here it's the place you go to attend classes every day.","grammar:5408:ex:points:1":"「学校に通う」 means going to school on a fixed, repeated basis.","grammar:5408:ex:points:2":"「ています」 expresses an ongoing habit or state at present.","grammar:5408:ex2:trans":"I made friends at school.","grammar:5408:ex2:structure":"学校で＋友達が＋できました","grammar:5408:ex2:words:0:zh":"school","grammar:5408:ex2:words:0:note":"がっこう","grammar:5408:ex2:words:0:pos":"noun","grammar:5408:ex2:words:1:zh":"exist","grammar:5408:ex2:words:1:pos":"particle","grammar:5408:ex2:words:2:zh":"friend","grammar:5408:ex2:words:2:note":"ともだち","grammar:5408:ex2:words:2:pos":"noun","grammar:5408:ex2:words:3:zh":"subject marker","grammar:5408:ex2:words:3:pos":"particle","grammar:5408:ex2:words:4:zh":"to come about, to form","grammar:5408:ex2:words:4:pos":"verb","grammar:5408:ex2:points:0":"「学校で」 shows that the place where it happened was school.","grammar:5408:ex2:points:1":"「友達ができる」 is the fixed expression for making a friend.","grammar:5408:ex3:trans":"A new school opened.","grammar:5408:ex3:structure":"新しい学校が＋オープンしました","grammar:5408:ex3:words:0:zh":"new","grammar:5408:ex3:words:0:note":"あたらしい","grammar:5408:ex3:words:0:pos":"adjective","grammar:5408:ex3:words:1:zh":"school","grammar:5408:ex3:words:1:note":"がっこう","grammar:5408:ex3:words:1:pos":"noun","grammar:5408:ex3:words:2:zh":"subject marker","grammar:5408:ex3:words:2:pos":"particle","grammar:5408:ex3:words:3:zh":"to open, to launch","grammar:5408:ex3:words:3:pos":"verb","grammar:5408:ex3:points:0":"Here 「学校」 refers to a newly founded or newly opened school.","grammar:5408:ex3:points:1":"「が」 marks the subject — the thing that opened.","grammar:5408:ex4:trans":"I like going to school.","grammar:5408:ex4:structure":"私は＋学校に行くのが＋好きです","grammar:5408:ex4:words:0:zh":"I","grammar:5408:ex4:words:0:note":"わたし","grammar:5408:ex4:words:0:pos":"pronoun","grammar:5408:ex4:words:1:zh":"marks the topic","grammar:5408:ex4:words:1:pos":"particle","grammar:5408:ex4:words:2:zh":"school","grammar:5408:ex4:words:2:note":"がっこう","grammar:5408:ex4:words:2:pos":"noun","grammar:5408:ex4:words:3:zh":"to, toward","grammar:5408:ex4:words:3:pos":"particle","grammar:5408:ex4:words:4:zh":"go","grammar:5408:ex4:words:4:note":"いく","grammar:5408:ex4:words:4:pos":"verb","grammar:5408:ex4:words:5:zh":"turns the action into a noun","grammar:5408:ex4:words:5:pos":"formal noun","grammar:5408:ex4:words:6:zh":"marker of what one likes","grammar:5408:ex4:words:6:pos":"particle","grammar:5408:ex4:words:7:zh":"to like","grammar:5408:ex4:words:7:note":"すき","grammar:5408:ex4:words:7:pos":"na-adjective","grammar:5408:ex4:words:8:zh":"is","grammar:5408:ex4:words:8:pos":"copula","grammar:5408:ex4:points:0":"「学校に行く」 means to go to school.","grammar:5408:ex4:points:1":"「行くの」 turns the action into a noun, making it the object of 「好き」.","grammar:5408:ex5:trans":"This school puts particular emphasis on English classes.","grammar:5408:ex5:structure":"この学校は＋名詞に＋特に＋力を入れています","grammar:5408:ex5:words:0:zh":"this","grammar:5408:ex5:words:0:pos":"pre-noun adjectival","grammar:5408:ex5:words:1:zh":"school","grammar:5408:ex5:words:1:note":"がっこう","grammar:5408:ex5:words:1:pos":"noun","grammar:5408:ex5:words:2:zh":"marks the topic","grammar:5408:ex5:words:2:pos":"particle","grammar:5408:ex5:words:3:zh":"English","grammar:5408:ex5:words:3:note":"えいご","grammar:5408:ex5:words:3:pos":"noun","grammar:5408:ex5:words:4:zh":"'s","grammar:5408:ex5:words:4:pos":"particle","grammar:5408:ex5:words:5:zh":"class","grammar:5408:ex5:words:5:note":"じゅぎょう","grammar:5408:ex5:words:5:pos":"noun","grammar:5408:ex5:words:6:zh":"(the area being focused on)","grammar:5408:ex5:words:6:pos":"particle","grammar:5408:ex5:words:7:zh":"special","grammar:5408:ex5:words:7:note":"とくに","grammar:5408:ex5:words:7:pos":"adverb","grammar:5408:ex5:words:8:zh":"effort","grammar:5408:ex5:words:8:note":"ちから","grammar:5408:ex5:words:8:pos":"noun","grammar:5408:ex5:words:9:zh":"object marker","grammar:5408:ex5:words:9:pos":"particle","grammar:5408:ex5:words:10:zh":"puts in","grammar:5408:ex5:words:10:note":"いれ；the stem of 「入れる」 (before て)","grammar:5408:ex5:words:10:pos":"verb","grammar:5408:ex5:words:11:zh":"links","grammar:5408:ex5:words:11:pos":"particle","grammar:5408:ex5:words:12:zh":"continues","grammar:5408:ex5:words:12:pos":"auxiliary verb","grammar:5408:ex5:words:13:zh":"polite ending","grammar:5408:ex5:words:13:pos":"auxiliary verb","grammar:5408:ex5:points:0":"「この学校は」 presents the topic, and what follows describes this school's distinguishing feature.","grammar:5408:ex5:points:1":"「〜に力を入れる」 is a fixed expression meaning to put special effort into some area.","grammar:5408:ex5:points:2":"「ています」 expresses a practice sustained over the long term.","exam:5408:zh":"The children go to school every day and learn reading and arithmetic from their teacher.","exam:5408:why":"「学校」 is where children learn reading and arithmetic from a teacher. 「病院」 is where you go for medical care, which doesn't fit the everyday learning scene in the sentence."},"5409":{"example:5409:exzh":"Blood flows through the veins.","example:5409:exzh2":"He was stabbed in the vein.","example:5409:exzh3":"I'm scheduled to have a vein test.","example:5409:exzh4":"Let's think about the health of our veins.","example:5409:exzh5":"The role of veins is very important."},"5410":{"example:5410:exzh":"That matter was never mentioned.","example:5410:exzh2":"He mentioned that problem.","example:5410:exzh3":"Mentioning it is important.","example:5410:exzh4":"This report mentions an important point.","example:5410:exzh5":"I'd like to refer to your opinion."},"5411":{"example:5411:exzh":"He's overstaying his welcome at home.","example:5411:exzh2":"Sometimes staying too long isn't a good thing.","example:5411:exzh3":"I want to stay for a long time during my vacation.","example:5411:exzh4":"A long stay can sometimes feel lonely.","example:5411:exzh5":"I enjoyed my long stay at my friend's house."},"5412":{"example:5412:exzh":"This course is three credits.","example:5412:exzh2":"It's hard to earn credits.","example:5412:exzh3":"He's worried because he doesn't have enough credits.","example:5412:exzh4":"The school's credit system has changed.","example:5412:exzh5":"You have to work hard to get credits."},"5413":{"example:5413:exzh":"They succeeded in containing the fire.","example:5413:exzh2":"Work to contain the virus is moving forward.","example:5413:exzh3":"He decided to contain the problem.","example:5413:exzh4":"Containment takes a lot of effort.","example:5413:exzh5":"The government is working to contain the infection."},"5414":{"example:5414:exzh":"His confession lightened his guilt.","example:5414:exzh2":"Sometimes you have to confess.","example:5414:exzh3":"The content of the confession will serve as evidence.","example:5414:exzh4":"After confessing, he was put on trial.","example:5414:exzh5":"Getting a confession takes time."},"5415":{"example:5415:exzh":"After I graduate, I want to move to the city and work.","example:5415:exzh2":"Life in the city is convenient.","example:5415:exzh3":"There are many people in the city.","example:5415:exzh4":"Traffic gets congested in the city.","example:5415:exzh5":"I grew up in the city."},"5416":{"example:5416:exzh":"This product is harmless.","example:5416:exzh2":"It's fine to touch harmless creatures.","example:5416:exzh3":"He is a harmless person.","example:5416:exzh4":"They use a harmless toxin.","example:5416:exzh5":"This medicine is harmless."},"5417":{"example:5417:exzh":"There are many stars in our galaxy.","example:5417:exzh2":"I'm researching that galaxy.","example:5417:exzh3":"A galaxy is a basic unit of the universe.","example:5417:exzh4":"She drew the shape of a galaxy.","example:5417:exzh5":"A new galaxy was discovered."},"5418":{"example:5418:exzh":"The house is on the south side.","example:5418:exzh2":"He lives in the room on the south side.","example:5418:exzh3":"The park on the south side is large.","example:5418:exzh4":"If you go to the south side, there's the sea.","example:5418:exzh5":"The south side of the building is bright."},"5419":{"example:5419:exzh":"I toured the school.","example:5419:exzh2":"Please tour this museum.","example:5419:exzh3":"The tour is very interesting.","example:5419:exzh4":"He toured the factory.","example:5419:exzh5":"After the tour, you can ask questions.","grammar:5419:ex:trans":"I toured the school.","grammar:5419:ex:structure":"学校を＋見学しました","grammar:5419:ex:explain":"「見学する」 (to tour, to visit) is a suru-verb formed from the noun 「見学」 plus 「する」. The place being toured takes 「を」, so 「学校を見学する」 = to tour a school. 「見学しました」 is the polite past form. Many Sino-Japanese nouns can take 「する」 to become verbs, following the pattern noun + 「を」 + noun + 「する」. The structure here is simple, making it a good example for practicing suru-verbs with an object.","grammar:5419:ex:words:0:zh":"school","grammar:5419:ex:words:0:note":"がっこう","grammar:5419:ex:words:0:pos":"noun","grammar:5419:ex:words:1:zh":"(object marker)","grammar:5419:ex:words:1:pos":"particle","grammar:5419:ex:words:2:zh":"tour","grammar:5419:ex:words:2:note":"けんがくしました","grammar:5419:ex:words:2:pos":"verb","grammar:5419:ex:points:0":"「学校を見学する」 = to tour a school","grammar:5419:ex:points:1":"「見学する」: a suru-verb formed from noun + する (to tour)","grammar:5419:ex2:trans":"Please tour this museum.","grammar:5419:ex2:structure":"博物館を＋見学してください","grammar:5419:ex2:words:0:zh":"this","grammar:5419:ex2:words:0:pos":"pre-noun adjectival","grammar:5419:ex2:words:1:zh":"museum","grammar:5419:ex2:words:1:note":"はくぶつかん","grammar:5419:ex2:words:1:pos":"noun","grammar:5419:ex2:words:2:zh":"(object marker)","grammar:5419:ex2:words:2:pos":"particle","grammar:5419:ex2:words:3:zh":"tour","grammar:5419:ex2:words:3:note":"けんがくして (te-form)","grammar:5419:ex2:words:3:pos":"verb","grammar:5419:ex2:words:4:zh":"please","grammar:5419:ex2:words:4:pos":"auxiliary verb","grammar:5419:ex2:points:0":"〜てください: please 〜 (見学してください)","grammar:5419:ex2:points:1":"pre-noun adjectival 「この」 + noun (this museum)","grammar:5419:ex3:trans":"The tour is very interesting.","grammar:5419:ex3:structure":"見学は とても＋興味深いです","grammar:5419:ex3:words:0:zh":"tour","grammar:5419:ex3:words:0:note":"けんがく","grammar:5419:ex3:words:0:pos":"noun","grammar:5419:ex3:words:1:zh":"(topic)","grammar:5419:ex3:words:1:pos":"particle","grammar:5419:ex3:words:2:zh":"extremely","grammar:5419:ex3:words:2:pos":"adverb","grammar:5419:ex3:words:3:zh":"intriguing; interesting","grammar:5419:ex3:words:3:note":"きょうみぶかい","grammar:5419:ex3:words:3:pos":"adjective","grammar:5419:ex3:words:4:zh":"(polite)","grammar:5419:ex3:words:4:pos":"auxiliary verb","grammar:5419:ex3:points:0":"The adjective 「興味深い」 = fascinating (+ です for politeness)","grammar:5419:ex3:points:1":"adverb 「とても」 = very (intensifies the degree)","grammar:5419:ex4:trans":"He toured the factory.","grammar:5419:ex4:structure":"工場を＋見学しました","grammar:5419:ex4:words:0:zh":"he","grammar:5419:ex4:words:0:note":"かれ","grammar:5419:ex4:words:0:pos":"pronoun","grammar:5419:ex4:words:1:zh":"(topic)","grammar:5419:ex4:words:1:pos":"particle","grammar:5419:ex4:words:2:zh":"factory","grammar:5419:ex4:words:2:note":"こうじょう","grammar:5419:ex4:words:2:pos":"noun","grammar:5419:ex4:words:3:zh":"(object marker)","grammar:5419:ex4:words:3:pos":"particle","grammar:5419:ex4:words:4:zh":"tour","grammar:5419:ex4:words:4:note":"けんがくしました","grammar:5419:ex4:words:4:pos":"verb","grammar:5419:ex4:points:0":"「工場を見学する」 = to tour a factory","grammar:5419:ex4:points:1":"AはBを見学する: A tours B","grammar:5419:ex5:trans":"After the tour, you can ask questions.","grammar:5419:ex5:structure":"見学の後＋質問ができます","grammar:5419:ex5:words:0:zh":"tour","grammar:5419:ex5:words:0:note":"けんがく","grammar:5419:ex5:words:0:pos":"noun","grammar:5419:ex5:words:1:zh":"'s","grammar:5419:ex5:words:1:pos":"particle","grammar:5419:ex5:words:2:zh":"later, afterwards","grammar:5419:ex5:words:2:note":"あと","grammar:5419:ex5:words:2:pos":"noun","grammar:5419:ex5:words:3:zh":"question","grammar:5419:ex5:words:3:note":"しつもん","grammar:5419:ex5:words:3:pos":"noun","grammar:5419:ex5:words:4:zh":"(nominative)","grammar:5419:ex5:words:4:pos":"particle","grammar:5419:ex5:words:5:zh":"can, to be able to","grammar:5419:ex5:words:5:pos":"verb","grammar:5419:ex5:points:0":"「〜の後」 = after 〜 (見学の後 = after the tour)","grammar:5419:ex5:points:1":"「質問ができる」 = to be able to ask questions"},"5420":{"example:5420:exzh":"My joints hurt.","example:5420:exzh2":"Exercise is good for the joints.","example:5420:exzh3":"She is a joint specialist.","example:5420:exzh4":"The movement of the joints is smooth.","example:5420:exzh5":"There are ways to relieve joint pain."},"5421":{"example:5421:exzh":"A fierce beast lives in that forest.","example:5421:exzh2":"You sometimes encounter a fierce beast.","example:5421:exzh3":"He is collecting photos of fierce beasts.","example:5421:exzh4":"Fierce beasts are rare in this area.","example:5421:exzh5":"A legendary fierce beast appeared."},"5422":{"example:5422:exzh":"A strong blast occurred.","example:5422:exzh2":"His blast was impressive.","example:5422:exzh3":"I heard the sound of a blast.","example:5422:exzh4":"Blasts are frequent in this area.","example:5422:exzh5":"Please be careful of blasts."},"5423":{"example:5423:exzh":"The bus arrived at the turnaround point.","example:5423:exzh2":"Please tell me the turnaround time.","example:5423:exzh3":"This road leads to the turnaround point.","example:5423:exzh4":"Where is the turnaround point?","example:5423:exzh5":"The turnaround fare is 500 yen."},"5424":{"example:5424:exzh":"His story is completely made up.","example:5424:exzh2":"Evidence of the fabrication was found.","example:5424:exzh3":"This news is said to be made up.","example:5424:exzh4":"Fabrications made to hide the truth are unforgivable.","example:5424:exzh5":"The fabrication against him is spreading."},"5425":{"example:5425:exzh":"He has a golden retriever.","example:5425:exzh2":"This gold bracelet is expensive.","example:5425:exzh3":"I'm going on a trip during Golden Week.","example:5425:exzh4":"That movie will be broadcast during golden hour.","example:5425:exzh5":"The golden-colored fish is beautiful."},"5426":{"example:5426:exzh":"The water bill went up.","example:5426:exzh2":"The plumbing in the neighborhood is broken.","example:5426:exzh3":"Can you drink the tap water in this area?","example:5426:exzh4":"The plumbing needs to be fixed.","example:5426:exzh5":"Water pipe construction is underway.","grammar:5426:ex:trans":"The water bill went up.","grammar:5426:ex:structure":"〔水道の料金〕＋が＋上がった. 「上がる」 is an intransitive verb.","grammar:5426:ex:explain":"This sentence is about telling transitive and intransitive verbs apart. 「上がる」 (to rise, to go up) is intransitive — the thing goes up by itself — and the subject of the rise takes 「が」: 「料金が上がる」 = the charge goes up. Its transitive counterpart is 「上げる」 (to raise). 「上がった」 is the plain past. 「水道の料金」 with 「の」 makes the charge for the water supply, i.e. the water bill. The whole sentence is the water bill went up; there is no human agent here, the price rose on its own.","grammar:5426:ex:words:0:zh":"tap water","grammar:5426:ex:words:0:note":"すいどう","grammar:5426:ex:words:0:pos":"noun","grammar:5426:ex:words:1:zh":"'s","grammar:5426:ex:words:1:pos":"particle","grammar:5426:ex:words:2:zh":"cost","grammar:5426:ex:words:2:note":"りょうきん","grammar:5426:ex:words:2:pos":"noun","grammar:5426:ex:words:3:zh":"(nominative)","grammar:5426:ex:words:3:pos":"particle","grammar:5426:ex:words:4:zh":"went up","grammar:5426:ex:words:4:note":"あがった","grammar:5426:ex:words:4:pos":"verb","grammar:5426:ex:points:0":"水道: the water supply (the pipes)","grammar:5426:ex:points:1":"料金が上がる: the charge goes up","grammar:5426:ex2:trans":"The water pipe nearby is broken.","grammar:5426:ex2:structure":"〔近所の水道〕＋が＋壊れています. 「壊れる」 is an intransitive verb, and 「〜ている」 shows the resulting state.","grammar:5426:ex2:words:0:zh":"nearby","grammar:5426:ex2:words:0:note":"きんじょ","grammar:5426:ex2:words:0:pos":"noun","grammar:5426:ex2:words:1:zh":"'s","grammar:5426:ex2:words:1:pos":"particle","grammar:5426:ex2:words:2:zh":"water pipe","grammar:5426:ex2:words:2:note":"すいどう","grammar:5426:ex2:words:2:pos":"noun","grammar:5426:ex2:words:3:zh":"(nominative)","grammar:5426:ex2:words:3:pos":"particle","grammar:5426:ex2:words:4:zh":"broke","grammar:5426:ex2:words:4:note":"〜ている expresses a state","grammar:5426:ex2:words:4:pos":"verb","grammar:5426:ex2:points:0":"壊れている: to be broken (state)","grammar:5426:ex2:points:1":"近所の水道: the water pipe nearby","grammar:5426:ex3:trans":"Is the tap water in this area drinkable?","grammar:5426:ex3:structure":"〔この地域の水道水〕＋は＋飲めますか. 「飲める」 is the potential form.","grammar:5426:ex3:words:0:zh":"this","grammar:5426:ex3:words:0:pos":"pre-noun adjectival","grammar:5426:ex3:words:1:zh":"area","grammar:5426:ex3:words:1:note":"ちいき","grammar:5426:ex3:words:1:pos":"noun","grammar:5426:ex3:words:2:zh":"'s","grammar:5426:ex3:words:2:pos":"particle","grammar:5426:ex3:words:3:zh":"tap water","grammar:5426:ex3:words:3:note":"すいどうすい","grammar:5426:ex3:words:3:pos":"noun","grammar:5426:ex3:words:4:zh":"(topic marker)","grammar:5426:ex3:words:4:pos":"particle","grammar:5426:ex3:words:5:zh":"can drink","grammar:5426:ex3:words:5:note":"のめます; potential form","grammar:5426:ex3:words:5:pos":"verb","grammar:5426:ex3:words:6:zh":"(question)","grammar:5426:ex3:words:6:pos":"particle","grammar:5426:ex3:points:0":"飲める: can drink (the potential form of 飲む)","grammar:5426:ex3:points:1":"水道水: tap water","grammar:5426:ex4:trans":"The water pipes need fixing.","grammar:5426:ex4:structure":"noun を＋〔直す＋必要があります〕. 「〜必要がある」 = need to …","grammar:5426:ex4:words:0:zh":"water pipe","grammar:5426:ex4:words:0:note":"すいどう","grammar:5426:ex4:words:0:pos":"noun","grammar:5426:ex4:words:1:zh":"(object marker)","grammar:5426:ex4:words:1:pos":"particle","grammar:5426:ex4:words:2:zh":"repair","grammar:5426:ex4:words:2:note":"なおす; dictionary form","grammar:5426:ex4:words:2:pos":"verb","grammar:5426:ex4:words:3:zh":"necessary","grammar:5426:ex4:words:3:note":"ひつよう","grammar:5426:ex4:words:3:pos":"na-adjective","grammar:5426:ex4:words:4:zh":"(nominative)","grammar:5426:ex4:words:4:pos":"particle","grammar:5426:ex4:words:5:zh":"there is / are","grammar:5426:ex4:words:5:note":"〜必要がある","grammar:5426:ex4:words:5:pos":"verb","grammar:5426:ex4:points:0":"〜必要がある: need to …","grammar:5426:ex4:points:1":"直す: to fix","grammar:5426:ex5:trans":"The water pipe work is underway.","grammar:5426:ex5:structure":"〔水道の工事〕＋が＋進んでいます. 「進む」 is an intransitive verb.","grammar:5426:ex5:words:0:zh":"water pipe","grammar:5426:ex5:words:0:note":"すいどう","grammar:5426:ex5:words:0:pos":"noun","grammar:5426:ex5:words:1:zh":"'s","grammar:5426:ex5:words:1:pos":"particle","grammar:5426:ex5:words:2:zh":"construction work","grammar:5426:ex5:words:2:note":"こうじ","grammar:5426:ex5:words:2:pos":"noun","grammar:5426:ex5:words:3:zh":"(nominative)","grammar:5426:ex5:words:3:pos":"particle","grammar:5426:ex5:words:4:zh":"carry out","grammar:5426:ex5:words:4:note":"すすんでいます; 〜ている shows ongoing progress","grammar:5426:ex5:words:4:pos":"verb","grammar:5426:ex5:points:0":"進む: (intransitive verb) to proceed, to move forward","grammar:5426:ex5:points:1":"水道の工事: the water pipe work"},"5427":{"example:5427:exzh":"You must not cross the road.","example:5427:exzh2":"He ran across the park.","example:5427:exzh3":"That car crossed the road.","example:5427:exzh4":"You need to be careful when crossing.","example:5427:exzh5":"There is a bridge that crosses the river."},"5428":{"example:5428:exzh":"The sushi has shrimp in it.","example:5428:exzh2":"I love fried shrimp.","example:5428:exzh3":"The shrimp soup is delicious.","example:5428:exzh4":"I bought shrimp yesterday.","example:5428:exzh5":"Shrimp are caught in the sea.","grammar:5428:ex:trans":"There's shrimp in the sushi.","grammar:5428:ex:structure":"noun に＋noun が＋入っています. 「〜に〜が入っている」 = there is … in …","grammar:5428:ex:explain":"This sentence uses 「〜に〜が入っている」 to say that something has something inside. The 「に」 in 「寿司に」 marks where it is, and 「エビが」 with 「が」 points out what's inside. 「入る」 is an intransitive verb; its te-form 「入って」 plus 「いる」 gives 「入っています」, which shows the resulting state of containing something, not that something is going in right now. This is a very common pattern for describing ingredients in food or what a package contains, with the feel of (at a glance) there's shrimp in it.","grammar:5428:ex:words:0:zh":"sushi","grammar:5428:ex:words:0:note":"すし","grammar:5428:ex:words:0:pos":"noun","grammar:5428:ex:words:1:zh":"(the place where something exists)","grammar:5428:ex:words:1:pos":"particle","grammar:5428:ex:words:2:zh":"shrimp","grammar:5428:ex:words:2:note":"Shrimp","grammar:5428:ex:words:2:pos":"noun","grammar:5428:ex:words:3:zh":"(nominative)","grammar:5428:ex:words:3:pos":"particle","grammar:5428:ex:words:4:zh":"contains","grammar:5428:ex:words:4:note":"はいっています; 〜ている expresses state","grammar:5428:ex:words:4:pos":"verb","grammar:5428:ex:points:0":"〜に〜が入っている: there is … in … / contains …","grammar:5428:ex:points:1":"エビ: shrimp","grammar:5428:ex2:trans":"I love fried shrimp.","grammar:5428:ex2:structure":"noun＋が＋大好きです。","grammar:5428:ex2:words:0:zh":"fried shrimp","grammar:5428:ex2:words:0:note":"fried shrimp (海老フライ)","grammar:5428:ex2:words:0:pos":"noun","grammar:5428:ex2:words:1:zh":"(object marker)","grammar:5428:ex2:words:1:pos":"particle","grammar:5428:ex2:words:2:zh":"loves most","grammar:5428:ex2:words:2:note":"だいすき","grammar:5428:ex2:words:2:pos":"na-adjective","grammar:5428:ex2:words:3:zh":"(polite form)","grammar:5428:ex2:words:3:pos":"copula","grammar:5428:ex2:points:0":"〜が大好きです: love …","grammar:5428:ex2:points:1":"エビフライ: fried shrimp","grammar:5428:ex3:trans":"The shrimp soup is delicious.","grammar:5428:ex3:structure":"〔エビのスープ〕＋は＋i-adjective＋です.","grammar:5428:ex3:words:0:zh":"shrimp","grammar:5428:ex3:words:0:note":"Shrimp","grammar:5428:ex3:words:0:pos":"noun","grammar:5428:ex3:words:1:zh":"'s","grammar:5428:ex3:words:1:pos":"particle","grammar:5428:ex3:words:2:zh":"soup","grammar:5428:ex3:words:2:note":"loanword soup","grammar:5428:ex3:words:2:pos":"noun","grammar:5428:ex3:words:3:zh":"(topic marker)","grammar:5428:ex3:words:3:pos":"particle","grammar:5428:ex3:words:4:zh":"tasty","grammar:5428:ex3:words:4:note":"おいしい","grammar:5428:ex3:words:4:pos":"adjective","grammar:5428:ex3:words:5:zh":"(polite form)","grammar:5428:ex3:words:5:pos":"copula","grammar:5428:ex3:points:0":"エビのスープ: shrimp soup","grammar:5428:ex3:points:1":"美味しい: tasty, delicious (for both drinks and food)","grammar:5428:ex4:trans":"I bought shrimp yesterday.","grammar:5428:ex4:structure":"time は、noun を＋買いました. 「昨日は」 = yesterday.","grammar:5428:ex4:words:0:zh":"yesterday","grammar:5428:ex4:words:0:note":"きのう","grammar:5428:ex4:words:0:pos":"noun","grammar:5428:ex4:words:1:zh":"(topic marker)","grammar:5428:ex4:words:1:pos":"particle","grammar:5428:ex4:words:2:zh":"shrimp","grammar:5428:ex4:words:2:note":"Shrimp","grammar:5428:ex4:words:2:pos":"noun","grammar:5428:ex4:words:3:zh":"(object marker)","grammar:5428:ex4:words:3:pos":"particle","grammar:5428:ex4:words:4:zh":"bought","grammar:5428:ex4:words:4:note":"かいました","grammar:5428:ex4:words:4:pos":"verb","grammar:5428:ex4:points:0":"昨日は: yesterday (topic)","grammar:5428:ex4:points:1":"エビ: shrimp","grammar:5428:ex5:trans":"Shrimp are caught in the sea.","grammar:5428:ex5:structure":"noun は＋place で＋捕れます. 「捕れる」 = can be caught, to be caught. 「で」 marks the place.","grammar:5428:ex5:words:0:zh":"shrimp","grammar:5428:ex5:words:0:note":"Shrimp","grammar:5428:ex5:words:0:pos":"noun","grammar:5428:ex5:words:1:zh":"(topic marker)","grammar:5428:ex5:words:1:pos":"particle","grammar:5428:ex5:words:2:zh":"sea","grammar:5428:ex5:words:2:note":"うみ","grammar:5428:ex5:words:2:pos":"noun","grammar:5428:ex5:words:3:zh":"(place of the action)","grammar:5428:ex5:words:3:pos":"particle","grammar:5428:ex5:words:4:zh":"can be caught","grammar:5428:ex5:words:4:note":"とれます; potential / spontaneous","grammar:5428:ex5:words:4:pos":"verb","grammar:5428:ex5:points:0":"捕れる: can be caught, catchable","grammar:5428:ex5:points:1":"で: place of the action (海で)"},"5430":{"example:5430:exzh":"I like fishing on the shore.","example:5430:exzh2":"The shore of the lake is beautiful.","example:5430:exzh3":"Waves are lapping at the shore.","example:5430:exzh4":"There are many ducks on the shore.","example:5430:exzh5":"I sit on the shore and soak up the sun."},"5431":{"example:5431:exzh":"The dog is inside the cage.","example:5431:exzh2":"Please prepare a cage for the cat too.","example:5431:exzh3":"This cage is too big.","example:5431:exzh4":"Cleaning the cage is a hassle.","example:5431:exzh5":"The bird is locked in a cage."},"5432":{"example:5432:exzh":"Maybe he'll come.","example:5432:exzh2":"Maybe it will rain.","example:5432:exzh3":"Maybe I made a mistake.","example:5432:exzh4":"Maybe I can go tomorrow.","example:5432:exzh5":"Maybe she'll come too."},"5433":{"example:5433:exzh":"He comes from a royal family.","example:5433:exzh2":"I'm reading a book about royalty.","example:5433:exzh3":"That country has an old royal family.","example:5433:exzh4":"I was invited to a royal event.","example:5433:exzh5":"The history of the royal family is very interesting."},"5434":{"example:5434:exzh":"She is a noble person.","example:5434:exzh2":"They have a noble spirit.","example:5434:exzh3":"His noble character is respected.","example:5434:exzh4":"I'm working hard toward a noble goal.","example:5434:exzh5":"Noble behavior is important."},"5435":{"example:5435:exzh":"She is learning ballet.","example:5435:exzh2":"I went to see a ballet performance.","example:5435:exzh3":"The ballet costumes are beautiful.","example:5435:exzh4":"Ballet is an elegant dance.","example:5435:exzh5":"I've loved ballet since I was a child."},"5436":{"example:5436:exzh":"Durian has a strong smell.","example:5436:exzh2":"He likes durian.","example:5436:exzh3":"Durian is called the king of fruits.","example:5436:exzh4":"I've eaten durian before.","example:5436:exzh5":"Durian is a fruit that people either love or hate."},"5437":{"example:5437:exzh":"He was clinging to his mother.","example:5437:exzh2":"The child is scared and clinging on.","example:5437:exzh3":"I clung to the tree and climbed up.","example:5437:exzh4":"Clinging on is dangerous.","example:5437:exzh5":"She clung to her friend."},"5438":{"example:5438:exzh":"He was egging his friend on.","example:5438:exzh2":"The man set the dog on the thief and made it chase him.","example:5438:exzh3":"Urged on by the people around him, he complained to his boss.","example:5438:exzh4":"You mustn't egg children on to play pranks.","example:5438:exzh5":"He egged his companions on to fight."},"5439":{"example:5439:exzh":"Please open the tube.","example:5439:exzh2":"This tube is empty.","example:5439:exzh3":"What's inside the tube?","example:5439:exzh4":"Please try using the tube.","example:5439:exzh5":"This tube is brand new."},"5440":{"example:5440:exzh":"He is good at creating comfortable spaces.","example:5440:exzh2":"Listening to pleasant music helps you relax.","example:5440:exzh3":"A warm bath feels nice.","example:5440:exzh4":"Spending time in nature feels good.","example:5440:exzh5":"She chose comfortable clothes."},"5441":{"example:5441:exzh":"Hounds are very loyal animals.","example:5441:exzh2":"He has a hound.","example:5441:exzh3":"Hounds are often used for hunting.","example:5441:exzh4":"Hounds were playing in the park.","example:5441:exzh5":"This hound is especially smart."},"5442":{"example:5442:exzh":"He got injured and bled.","example:5442:exzh2":"If the bleeding doesn't stop, you should go to a doctor.","example:5442:exzh3":"You need to be careful with injuries that involve bleeding.","example:5442:exzh4":"It's important to check the cause of the bleeding.","example:5442:exzh5":"He is strong even when he bleeds."},"5443":{"example:5443:exzh":"He crushed the ice and put it in a drink.","example:5443:exzh2":"Crushing a big rock is hard work.","example:5443:exzh3":"Something happened that took a lot of effort and worry.","example:5443:exzh4":"Her dream was shattered.","example:5443:exzh5":"This machine can crush wood."},"5444":{"example:5444:exzh":"He shot at the goal.","example:5444:exzh2":"I missed the shot, so I'm frustrated.","example:5444:exzh3":"A great shot went in!","example:5444:exzh4":"I practiced shooting and made my arms stronger.","example:5444:exzh5":"The goalkeeper blocked the shot."},"5445":{"example:5445:exzh":"We cross the river by ferry.","example:5445:exzh2":"There's a ferry, which is a big help.","example:5445:exzh3":"He's the ferry driver.","example:5445:exzh4":"On weekends I ride the ferry with my family.","example:5445:exzh5":"This ferry is very convenient."},"5446":{"example:5446:exzh":"I have a friend who works on a farm.","example:5446:exzh2":"This farm grows fresh vegetables.","example:5446:exzh3":"I like helping farmers.","example:5446:exzh4":"Farm life is hard, but it's fun.","example:5446:exzh5":"There are many farms in this area."},"5447":{"example:5447:exzh":"Breeding dogs requires a lot of knowledge.","example:5447:exzh2":"This animal is difficult to breed.","example:5447:exzh3":"It's important to understand the breeding process.","example:5447:exzh4":"Breeding requires specialized care.","example:5447:exzh5":"He's interested in animal breeding."},"5448":{"example:5448:exzh":"I created a new account.","example:5448:exzh2":"I forgot the account password.","example:5448:exzh3":"This account is free.","example:5448:exzh4":"I plan to delete the account.","example:5448:exzh5":"Why did you report that account?"},"5449":{"example:5449:exzh":"He defeated his enemy in the match.","example:5449:exzh2":"She practiced so she could defeat her rival.","example:5449:exzh3":"Keep taking on challenges without being beaten down.","example:5449:exzh4":"This experience left him crushed.","example:5449:exzh5":"Unexpectedly, I felt crushed."},"5450":{"example:5450:exzh":"I'm reading the manual for the new machine.","example:5450:exzh2":"Please do the work according to the manual.","example:5450:exzh3":"This manual is really useful.","example:5450:exzh4":"I printed the manual.","example:5450:exzh5":"That problem is explained in the manual."},"5451":{"example:5451:exzh":"He was revived after the accident.","example:5451:exzh2":"It's important to learn resuscitation techniques.","example:5451:exzh3":"With her help, he was revived.","example:5451:exzh4":"I received training in CPR.","example:5451:exzh5":"The success rate of resuscitation is high."},"5452":{"example:5452:exzh":"This device cools down quickly.","example:5452:exzh2":"We use a fan for cooling.","example:5452:exzh3":"Cooling technology has advanced.","example:5452:exzh4":"If the cooling is insufficient, it may break down.","example:5452:exzh5":"The kitchen needs a fan for cooling."},"5453":{"example:5453:exzh":"There's a sofa in the living room.","example:5453:exzh2":"I relaxed on the sofa.","example:5453:exzh3":"I want to buy a new sofa.","example:5453:exzh4":"I chose the color of the sofa.","example:5453:exzh5":"The sofa is very comfortable.","grammar:5453:ex:trans":"There is a sofa in the living room.","grammar:5453:ex:structure":"リビングに、ソファーが＋あります。「ソファー」＝ sofa, 「リビング」＝ living room.","grammar:5453:ex:explain":"This is the existence pattern for inanimate things, 「〜に〜があります」. In 「リビングに」, the 「に」 marks the place where something exists, the living room; 「ソファーが」 uses 「が」 to point out the thing that exists, a sofa; and 「あります」 is the polite form of 「ある」, used for inanimate things. The whole sentence describes there being a sofa in the living room. This 「場所に＋物が＋あります」 form is the basic pattern for saying what is somewhere.","grammar:5453:ex:words:0:zh":"living room","grammar:5453:ex:words:0:note":"loanword","grammar:5453:ex:words:0:pos":"noun","grammar:5453:ex:words:1:zh":"(the place where something exists)","grammar:5453:ex:words:1:pos":"particle","grammar:5453:ex:words:2:zh":"sofa","grammar:5453:ex:words:2:note":"loanword: sofa","grammar:5453:ex:words:2:pos":"noun","grammar:5453:ex:words:3:zh":"(nominative)","grammar:5453:ex:words:3:pos":"particle","grammar:5453:ex:words:4:zh":"there is / are","grammar:5453:ex:words:4:note":"exists / there is","grammar:5453:ex:words:4:pos":"verb","grammar:5453:ex:points:0":"ソファー：sofa","grammar:5453:ex:points:1":"リビングにソファーがある：there is a sofa in the living room","grammar:5453:ex2:trans":"I relaxed on the sofa.","grammar:5453:ex2:structure":"ソファーで、くつろぎました。「ソファーでくつろぐ」＝ to relax on the sofa.","grammar:5453:ex2:words:0:zh":"sofa","grammar:5453:ex2:words:0:note":"loanword","grammar:5453:ex2:words:0:pos":"noun","grammar:5453:ex2:words:1:zh":"(place of the action)","grammar:5453:ex2:words:1:pos":"particle","grammar:5453:ex2:words:2:zh":"relaxed","grammar:5453:ex2:words:2:note":"寛ぎました","grammar:5453:ex2:words:2:pos":"verb","grammar:5453:ex2:points:0":"ソファーでくつろぐ：to relax on the sofa","grammar:5453:ex2:points:1":"くつろぐ：to relax, to unwind","grammar:5453:ex3:trans":"I want to buy a new sofa.","grammar:5453:ex3:structure":"〔新しいソファー〕＋を＋買いたいです。「新しいソファー」＝ a new sofa.","grammar:5453:ex3:words:0:zh":"new","grammar:5453:ex3:words:0:note":"あたらしい","grammar:5453:ex3:words:0:pos":"adjective","grammar:5453:ex3:words:1:zh":"sofa","grammar:5453:ex3:words:1:note":"loanword","grammar:5453:ex3:words:1:pos":"noun","grammar:5453:ex3:words:2:zh":"(object marker)","grammar:5453:ex3:words:2:pos":"particle","grammar:5453:ex3:words:3:zh":"want to buy","grammar:5453:ex3:words:3:note":"〜たい expresses desire","grammar:5453:ex3:words:3:pos":"verb","grammar:5453:ex3:words:4:zh":"(polite form)","grammar:5453:ex3:words:4:pos":"copula","grammar:5453:ex3:points:0":"新しいソファー：a new sofa","grammar:5453:ex3:points:1":"買いたい：want to buy","grammar:5453:ex4:trans":"I chose the color of the sofa.","grammar:5453:ex4:structure":"〔ソファーの色〕＋を＋選びました。「ソファーの色」＝ the color of the sofa.","grammar:5453:ex4:words:0:zh":"sofa","grammar:5453:ex4:words:0:note":"loanword","grammar:5453:ex4:words:0:pos":"noun","grammar:5453:ex4:words:1:zh":"'s","grammar:5453:ex4:words:1:pos":"particle","grammar:5453:ex4:words:2:zh":"color","grammar:5453:ex4:words:2:note":"いろ","grammar:5453:ex4:words:2:pos":"noun","grammar:5453:ex4:words:3:zh":"(object marker)","grammar:5453:ex4:words:3:pos":"particle","grammar:5453:ex4:words:4:zh":"chose","grammar:5453:ex4:words:4:note":"えらびました","grammar:5453:ex4:words:4:pos":"verb","grammar:5453:ex4:points:0":"ソファーの色：the color of the sofa","grammar:5453:ex4:points:1":"色を選ぶ：to choose a color","grammar:5453:ex5:trans":"The sofa is very comfortable.","grammar:5453:ex5:structure":"ソファーは、とても＋快適です。「快適」＝ comfortable.","grammar:5453:ex5:words:0:zh":"sofa","grammar:5453:ex5:words:0:note":"loanword","grammar:5453:ex5:words:0:pos":"noun","grammar:5453:ex5:words:1:zh":"(topic marker)","grammar:5453:ex5:words:1:pos":"particle","grammar:5453:ex5:words:2:zh":"extremely","grammar:5453:ex5:words:2:pos":"adverb","grammar:5453:ex5:words:3:zh":"comfortable","grammar:5453:ex5:words:3:note":"かいてき","grammar:5453:ex5:words:3:pos":"na-adjective","grammar:5453:ex5:words:4:zh":"(polite form)","grammar:5453:ex5:words:4:pos":"copula","grammar:5453:ex5:points:0":"ソファー：sofa","grammar:5453:ex5:points:1":"快適: comfortable"},"5454":{"example:5454:exzh":"He has strong perseverance.","example:5454:exzh2":"You can't succeed without enough perseverance.","example:5454:exzh3":"Effort and perseverance are needed.","example:5454:exzh4":"She overcame the difficulty through perseverance.","example:5454:exzh5":"If you show perseverance, your dreams will come true."},"5455":{"example:5455:exzh":"I argued against his opinion.","example:5455:exzh2":"Rebuttal is part of a debate.","example:5455:exzh3":"It's important to be able to argue against your own claims.","example:5455:exzh4":"If you have any objections, please let me know.","example:5455:exzh5":"There's room to argue against that claim."},"5457":{"example:5457:exzh":"I'm confident I can love you.","example:5457:exzh2":"There's no one who couldn't love this cat.","example:5457:exzh3":"I want to be able to love him.","example:5457:exzh4":"Being able to love your family is the most important thing.","example:5457:exzh5":"I want to meet someone I can love from the bottom of my heart."},"5458":{"example:5458:exzh":"The room is a mess.","example:5458:exzh2":"Kids always leave their toys scattered around.","example:5458:exzh3":"Please don't leave things scattered around.","example:5458:exzh4":"He likes a messy house.","example:5458:exzh5":"Let's clean up after making a mess."},"5459":{"example:5459:exzh":"I believe he isn't an alcoholic.","example:5459:exzh2":"Rehab for alcoholism is tough.","example:5459:exzh3":"Alcoholism is one of society's problems.","example:5459:exzh4":"She overcame alcoholism.","example:5459:exzh5":"I'll take part in treatment for alcoholism."},"5460":{"example:5460:exzh":"You have to accept fate.","example:5460:exzh2":"He resolved to face his fate.","example:5460:exzh3":"Following fate is also important.","example:5460:exzh4":"It's hard to go against fate.","example:5460:exzh5":"Knowing your fate is scary."},"5462":{"example:5462:exzh":"Please don't interfere in anything.","example:5462:exzh2":"He's always sticking his nose in.","example:5462:exzh3":"I don't plan to interfere.","example:5462:exzh4":"If you interfere, problems might come up.","example:5462:exzh5":"It's better not to interfere too much."},"5463":{"example:5463:exzh":"I often use hand cream in winter.","example:5463:exzh2":"She's good at handball.","example:5463:exzh3":"After I put on hand cream, my hand slipped.","example:5463:exzh4":"I have a handbag.","example:5463:exzh5":"I communicate using hand signals."},"5464":{"example:5464:exzh":"We need to verify the results.","example:5464:exzh2":"His research hasn't been verified.","example:5464:exzh3":"We will verify all the evidence.","example:5464:exzh4":"The verification work is difficult.","example:5464:exzh5":"Almost all of this data has been verified."},"5465":{"example:5465:exzh":"This hall is spacious.","example:5465:exzh2":"There's a meeting in the auditorium.","example:5465:exzh3":"He's performing in the concert hall.","example:5465:exzh4":"In the temple hall, I quietly put my hands together in prayer.","example:5465:exzh5":"There's an event at the city cultural hall."},"5466":{"example:5466:exzh":"I like making stew.","example:5466:exzh2":"I'm having stew today.","example:5466:exzh3":"The whole family made stew together.","example:5466:exzh4":"This stew is really delicious.","example:5466:exzh5":"I dip bread in the stew and eat it."},"5467":{"example:5467:exzh":"A new problem came up in the meeting.","example:5467:exzh2":"Every time a problem comes up, he worries.","example:5467:exzh3":"A new idea came up.","example:5467:exzh4":"Because an accident happened, the discussion came up.","example:5467:exzh5":"Something that's been on my mind has come up, so we need to talk it over."},"5468":{"example:5468:exzh":"Please take charge of this project.","example:5468:exzh2":"Please give him my regards.","example:5468:exzh3":"Looking forward to working with you at the new job.","example:5468:exzh4":"Everyone, I look forward to working with you.","example:5468:exzh5":"Please take good care of him.","grammar:5468:ex:trans":"Please take care of this project.","grammar:5468:ex:structure":"この＋名詞を＋宜しくお願いします. 「〜を宜しくお願いします」 = I am counting on you for this.","grammar:5468:ex:explain":"This is the fixed everyday phrase 「〜を宜しくお願いします」, meaning I am counting on you for …, with the thing being entrusted marked by 「を」. 「宜しく」 is an adverb meaning please treat it favorably, and 「お願いします」 is the humble, polite form of 「願う」, meaning to request or ask. The phrase is used when handing a matter over to someone, in a courteous and fairly formal tone. The whole sentence means I am counting on you for this project, and it is an extremely common request pattern at work and in social settings.","grammar:5468:ex:words:0:zh":"this","grammar:5468:ex:words:0:pos":"pre-noun adjectival","grammar:5468:ex:words:1:zh":"project","grammar:5468:ex:words:1:note":"loanword","grammar:5468:ex:words:1:pos":"noun","grammar:5468:ex:words:2:zh":"(object marker)","grammar:5468:ex:words:2:pos":"particle","grammar:5468:ex:words:3:zh":"please treat me well","grammar:5468:ex:words:3:note":"よろしく","grammar:5468:ex:words:3:pos":"adverb","grammar:5468:ex:words:4:zh":"please","grammar:5468:ex:words:4:note":"set phrase for requests","grammar:5468:ex:words:4:pos":"verb","grammar:5468:ex:points:0":"〜を宜しくお願いします: I am counting on you for …","grammar:5468:ex:points:1":"宜しく: please treat me well (adverb)","grammar:5468:ex2:trans":"Please give him my regards.","grammar:5468:ex2:structure":"名詞に＋宜しく＋伝えてください. 「〜に宜しく伝える」 = pass on my regards to …","grammar:5468:ex2:words:0:zh":"he","grammar:5468:ex2:words:0:note":"かれ","grammar:5468:ex2:words:0:pos":"pronoun","grammar:5468:ex2:words:1:zh":"(object)","grammar:5468:ex2:words:1:pos":"particle","grammar:5468:ex2:words:2:zh":"Greeting","grammar:5468:ex2:words:2:note":"よろしく; here it stands for words of greeting","grammar:5468:ex2:words:2:pos":"adverb","grammar:5468:ex2:words:3:zh":"pass on (a message)","grammar:5468:ex2:words:3:note":"te-form","grammar:5468:ex2:words:3:pos":"verb","grammar:5468:ex2:words:4:zh":"please","grammar:5468:ex2:words:4:note":"〜てください","grammar:5468:ex2:words:4:pos":"verb","grammar:5468:ex2:points:0":"〜に宜しく伝える: pass on regards to … on someone's behalf","grammar:5468:ex2:points:1":"宜しく: (pass on) regards","grammar:5468:ex3:trans":"Please treat me well at my new job.","grammar:5468:ex3:structure":"〔新しい仕事〕＋で、宜しくです. 「宜しくです」 = please treat me well (a casual way of saying it).","grammar:5468:ex3:words:0:zh":"new","grammar:5468:ex3:words:0:note":"あたらしい","grammar:5468:ex3:words:0:pos":"adjective","grammar:5468:ex3:words:1:zh":"work","grammar:5468:ex3:words:1:note":"しごと","grammar:5468:ex3:words:1:pos":"noun","grammar:5468:ex3:words:2:zh":"(scene)","grammar:5468:ex3:words:2:pos":"particle","grammar:5468:ex3:words:3:zh":"please treat me well","grammar:5468:ex3:words:3:note":"よろしく","grammar:5468:ex3:words:3:pos":"adverb","grammar:5468:ex3:words:4:zh":"(polite form)","grammar:5468:ex3:words:4:pos":"copula","grammar:5468:ex3:points:0":"宜しくです: please treat me well (casual speech)","grammar:5468:ex3:points:1":"宜しく: please treat me well","grammar:5468:ex4:trans":"Everyone, I look forward to working with you.","grammar:5468:ex4:structure":"皆さん、宜しくお願いします. 「宜しくお願いします」 = please treat me well / I look forward to working with you.","grammar:5468:ex4:words:0:zh":"everyone","grammar:5468:ex4:words:0:note":"みなさん","grammar:5468:ex4:words:0:pos":"noun","grammar:5468:ex4:words:1:zh":"please treat me well","grammar:5468:ex4:words:1:note":"よろしく","grammar:5468:ex4:words:1:pos":"adverb","grammar:5468:ex4:words:2:zh":"please","grammar:5468:ex4:words:2:note":"set phrase for requests","grammar:5468:ex4:words:2:pos":"verb","grammar:5468:ex4:points:0":"宜しくお願いします: please treat me well / please look after me","grammar:5468:ex4:points:1":"皆さん：everyone (polite)","grammar:5468:ex5:trans":"Please take good care of him.","grammar:5468:ex5:structure":"名詞を＋宜しくお願いします. 「〜を宜しくお願いします」 = please take good care of …","grammar:5468:ex5:words:0:zh":"he","grammar:5468:ex5:words:0:note":"かれ","grammar:5468:ex5:words:0:pos":"pronoun","grammar:5468:ex5:words:1:zh":"(object marker)","grammar:5468:ex5:words:1:pos":"particle","grammar:5468:ex5:words:2:zh":"please take good care of","grammar:5468:ex5:words:2:note":"よろしく","grammar:5468:ex5:words:2:pos":"adverb","grammar:5468:ex5:words:3:zh":"please","grammar:5468:ex5:words:3:note":"set phrase for requests","grammar:5468:ex5:words:3:pos":"verb","grammar:5468:ex5:points:0":"〜を宜しくお願いします: please take good care of … / look after …","grammar:5468:ex5:points:1":"宜しく: please treat me well"},"5469":{"example:5469:exzh":"I work in real estate brokerage.","example:5469:exzh2":"Thanks to his mediation, the contract was finalized.","example:5469:exzh3":"I'm looking for a company with low brokerage fees.","example:5469:exzh4":"We made the deal directly without going through a broker.","example:5469:exzh5":"I'm thinking about using a brokerage service."},"5470":{"example:5470:exzh":"There are trolls online, so you need to be careful.","example:5470:exzh2":"Strict measures are being taken against trolling.","example:5470:exzh3":"Trolls have become a problem on a certain forum.","example:5470:exzh4":"Let's all do our best so we don't give in to the trolls.","example:5470:exzh5":"I blocked the trolling comment."},"5471":{"example:5471:exzh":"We formed a new team.","example:5471:exzh2":"We discussed the reasons behind the formation.","example:5471:exzh3":"This organization was formed to promote peace.","example:5471:exzh4":"It was formed together with companions.","example:5471:exzh5":"A year has passed since it was formed."},"5472":{"example:5472:exzh":"The train started moving.","example:5472:exzh2":"The rocket launch was successful.","example:5472:exzh3":"This plane is scheduled to depart at 2 p.m.","example:5472:exzh4":"Please wait a moment until the bus departs.","example:5472:exzh5":"I heard the signal to depart."},"5473":{"example:5473:exzh":"It's hard to understand his true nature.","example:5473:exzh2":"He isn't a bad person at heart.","example:5473:exzh3":"To solve this problem, it's important to discern true nature.","example:5473:exzh4":"The true nature came out.","example:5473:exzh5":"She's kind by nature."},"5474":{"example:5474:exzh":"This meeting is dragging on.","example:5474:exzh2":"If it drags on, time will be wasted.","example:5474:exzh3":"If the conversation drags on, it gets tiring.","example:5474:exzh4":"The problem is dragging on and can't be solved.","example:5474:exzh5":"The work may drag on."},"5475":{"example:5475:exzh":"Extracting data is a difficult task.","example:5475:exzh2":"This method can extract the components.","example:5475:exzh3":"Let's extract the compound from the sample.","example:5475:exzh4":"You need to be careful when extracting.","example:5475:exzh5":"Please report the extraction results."},"5476":{"example:5476:exzh":"A small airplane is flying in the sky.","example:5476:exzh2":"Small dogs are cute.","example:5476:exzh3":"This company makes small robots.","example:5476:exzh4":"I'm looking for a small part.","example:5476:exzh5":"Small cameras are easy to carry around."},"5477":{"example:5477:exzh":"The royal family is a symbol of the country.","example:5477:exzh2":"He was born into the royal family.","example:5477:exzh3":"I learned about the history of the royal family.","example:5477:exzh4":"This festival is connected to the royal family.","example:5477:exzh5":"A ceremony of the royal family was held."},"5478":{"example:5478:exzh":"She is wearing a green dress.","example:5478:exzh2":"A green meadow stretches out.","example:5478:exzh3":"Her green eyes are her distinguishing feature.","example:5478:exzh4":"I like green.","example:5478:exzh5":"There are many green fruits.","grammar:5478:ex:trans":"She is wearing a green dress.","grammar:5478:ex:structure":"〜は＋〔緑色のドレス〕＋を＋着ています. 「緑色の」 = green.","grammar:5478:ex:explain":"The key point here is 「〜を着ている」, which describes the state of wearing something. The te-form of 「着る」 (wear), 「着て」, plus 「いる」 gives 「着ています」; here 「〜ている」 does not mean the act of putting something on but the resulting state of wearing it. The thing worn takes 「を」, and 「緑色のドレス」 is modified by 「の」 to mean green dress. 「彼女は」 sets the topic. The whole sentence means she is wearing a green dress. To describe what someone has on, 「〜を着ている」 is the usual choice.","grammar:5478:ex:words:0:zh":"she","grammar:5478:ex:words:0:note":"かのじょ","grammar:5478:ex:words:0:pos":"pronoun","grammar:5478:ex:words:1:zh":"(topic marker)","grammar:5478:ex:words:1:pos":"particle","grammar:5478:ex:words:2:zh":"green","grammar:5478:ex:words:2:note":"みどりいろ","grammar:5478:ex:words:2:pos":"noun","grammar:5478:ex:words:3:zh":"'s","grammar:5478:ex:words:3:pos":"particle","grammar:5478:ex:words:4:zh":"dress","grammar:5478:ex:words:4:note":"loanword","grammar:5478:ex:words:4:pos":"noun","grammar:5478:ex:words:5:zh":"(object marker)","grammar:5478:ex:words:5:pos":"particle","grammar:5478:ex:words:6:zh":"Wearing","grammar:5478:ex:words:6:note":"〜ている expresses a state","grammar:5478:ex:words:6:pos":"verb","grammar:5478:ex:points:0":"〜色の＋noun: …-colored … (緑色のドレス = green dress)","grammar:5478:ex:points:1":"〜を着ている: to be wearing…","grammar:5478:ex2:trans":"A green meadow stretches out.","grammar:5478:ex2:structure":"〔緑色の草原〕＋が＋広がっています。","grammar:5478:ex2:words:0:zh":"green","grammar:5478:ex2:words:0:note":"みどりいろ","grammar:5478:ex2:words:0:pos":"noun","grammar:5478:ex2:words:1:zh":"'s","grammar:5478:ex2:words:1:pos":"particle","grammar:5478:ex2:words:2:zh":"meadow","grammar:5478:ex2:words:2:note":"そうげん","grammar:5478:ex2:words:2:pos":"noun","grammar:5478:ex2:words:3:zh":"(nominative)","grammar:5478:ex2:words:3:pos":"particle","grammar:5478:ex2:words:4:zh":"to unfold, to spread out","grammar:5478:ex2:words:4:note":"ひろがっています; 〜ている shows a state","grammar:5478:ex2:words:4:pos":"verb","grammar:5478:ex2:points:0":"緑色の草原: green meadow","grammar:5478:ex2:points:1":"広がる: to spread out, to open up","grammar:5478:ex3:trans":"Her green eyes are her distinguishing feature.","grammar:5478:ex3:structure":"〔緑色の目〕＋が＋名詞です. 「〜が特徴」 = … is the distinguishing feature.","grammar:5478:ex3:words:0:zh":"green","grammar:5478:ex3:words:0:note":"みどりいろ","grammar:5478:ex3:words:0:pos":"noun","grammar:5478:ex3:words:1:zh":"'s","grammar:5478:ex3:words:1:pos":"particle","grammar:5478:ex3:words:2:zh":"eye(s)","grammar:5478:ex3:words:2:note":"め","grammar:5478:ex3:words:2:pos":"noun","grammar:5478:ex3:words:3:zh":"(nominative)","grammar:5478:ex3:words:3:pos":"particle","grammar:5478:ex3:words:4:zh":"distinguishing feature","grammar:5478:ex3:words:4:note":"とくちょう","grammar:5478:ex3:words:4:pos":"noun","grammar:5478:ex3:words:5:zh":"is","grammar:5478:ex3:words:5:pos":"copula","grammar:5478:ex3:points:0":"〜が特徴です: … is the distinctive feature","grammar:5478:ex3:points:1":"緑色の目: green eyes","grammar:5478:ex4:trans":"I like green.","grammar:5478:ex4:structure":"〜は＋noun＋が＋好きです.","grammar:5478:ex4:words:0:zh":"I","grammar:5478:ex4:words:0:note":"わたし","grammar:5478:ex4:words:0:pos":"pronoun","grammar:5478:ex4:words:1:zh":"(topic marker)","grammar:5478:ex4:words:1:pos":"particle","grammar:5478:ex4:words:2:zh":"green","grammar:5478:ex4:words:2:note":"みどりいろ","grammar:5478:ex4:words:2:pos":"noun","grammar:5478:ex4:words:3:zh":"(object marker)","grammar:5478:ex4:words:3:pos":"particle","grammar:5478:ex4:words:4:zh":"to like","grammar:5478:ex4:words:4:note":"すき","grammar:5478:ex4:words:4:pos":"na-adjective","grammar:5478:ex4:words:5:zh":"(polite form)","grammar:5478:ex4:words:5:pos":"copula","grammar:5478:ex4:points:0":"〜が好きです: like …","grammar:5478:ex4:points:1":"緑色: green","grammar:5478:ex5:trans":"There are lots of green fruits.","grammar:5478:ex5:structure":"〔緑色の果物〕＋が＋たくさん＋あります。","grammar:5478:ex5:words:0:zh":"green","grammar:5478:ex5:words:0:note":"みどりいろ","grammar:5478:ex5:words:0:pos":"noun","grammar:5478:ex5:words:1:zh":"'s","grammar:5478:ex5:words:1:pos":"particle","grammar:5478:ex5:words:2:zh":"fruit","grammar:5478:ex5:words:2:note":"くだもの","grammar:5478:ex5:words:2:pos":"noun","grammar:5478:ex5:words:3:zh":"(nominative)","grammar:5478:ex5:words:3:pos":"particle","grammar:5478:ex5:words:4:zh":"a lot","grammar:5478:ex5:words:4:pos":"adverb","grammar:5478:ex5:words:5:zh":"there is / are","grammar:5478:ex5:words:5:note":"exists / there is","grammar:5478:ex5:words:5:pos":"verb","grammar:5478:ex5:points:0":"緑色の果物: green fruit","grammar:5478:ex5:points:1":"たくさんある: there are many"},"5479":{"example:5479:exzh":"This information is spreading.","example:5479:exzh2":"New technology spreads quickly.","example:5479:exzh3":"His fame spread quickly.","example:5479:exzh4":"As culture spreads, understanding deepens.","example:5479:exzh5":"This custom is gradually spreading."},"5480":{"example:5480:exzh":"When night ends, a new day begins.","example:5480:exzh2":"Winter ends and spring comes.","example:5480:exzh3":"Happy New Year!","example:5480:exzh4":"Once the rainy season ends, the real summer begins.","example:5480:exzh5":"Once the new year begins, I intend to look for a new job."},"5481":{"example:5481:exzh":"I spread honey on the bread.","example:5481:exzh2":"He loves honey.","example:5481:exzh3":"Honey is good for your health.","example:5481:exzh4":"I added honey to the tea.","example:5481:exzh5":"The children eat honey as a snack."},"5482":{"example:5482:exzh":"The fortress plays an important role in defense.","example:5482:exzh2":"I visited a historic fortress.","example:5482:exzh3":"This fortress was built to protect the town from enemies.","example:5482:exzh4":"There is a village near the fortress.","example:5482:exzh5":"The old fortress is a tourist attraction."},"5483":{"example:5483:exzh":"His charm draws people in.","example:5483:exzh2":"This theory attracts many people.","example:5483:exzh3":"Good energy attracts good things.","example:5483:exzh4":"Her words drew people in.","example:5483:exzh5":"Successful people attract positive energy."},"5484":{"example:5484:exzh":"I like hamburgers.","example:5484:exzh2":"I ate a hamburger for lunch.","example:5484:exzh3":"Hamburgers are one kind of fast food.","example:5484:exzh4":"I ordered a hamburger.","example:5484:exzh5":"I ate hamburgers with a friend.","grammar:5484:ex:trans":"I like hamburgers.","grammar:5484:ex:structure":"〜は＋noun＋が＋好きです.","grammar:5484:ex:explain":"This is the most basic sentence for likes and dislikes: 「〜は〜が好きです」. The thing you like, 「ハンバーガー」, is marked with the subject particle 「が」 rather than the object marker 「を」, because 「好き」 is a na-adjective, not a verb. 「私は」 uses 「は」 to present me as the topic, giving the two-particle shape (I) ＋ topic は ＋ object が ＋ 好き. 「です」 is the polite copula. The whole sentence means I like hamburgers, and it is the standard beginner sentence for expressing likes and dislikes.","grammar:5484:ex:words:0:zh":"I","grammar:5484:ex:words:0:note":"わたし","grammar:5484:ex:words:0:pos":"pronoun","grammar:5484:ex:words:1:zh":"(topic marker)","grammar:5484:ex:words:1:pos":"particle","grammar:5484:ex:words:2:zh":"hamburger","grammar:5484:ex:words:2:note":"loanword: hamburger","grammar:5484:ex:words:2:pos":"noun","grammar:5484:ex:words:3:zh":"(object marker)","grammar:5484:ex:words:3:pos":"particle","grammar:5484:ex:words:4:zh":"to like","grammar:5484:ex:words:4:note":"すき","grammar:5484:ex:words:4:pos":"na-adjective","grammar:5484:ex:words:5:zh":"(polite form)","grammar:5484:ex:words:5:pos":"copula","grammar:5484:ex:points:0":"〜が好きです: like …","grammar:5484:ex:points:1":"ハンバーガー: hamburger","grammar:5484:ex2:trans":"I had a hamburger for lunch.","grammar:5484:ex2:structure":"時間に＋名詞を＋食べました. 「昼ごはんに」 = at lunchtime.","grammar:5484:ex2:words:0:zh":"lunch","grammar:5484:ex2:words:0:note":"ひるごはん","grammar:5484:ex2:words:0:pos":"noun","grammar:5484:ex2:words:1:zh":"(point in time)","grammar:5484:ex2:words:1:pos":"particle","grammar:5484:ex2:words:2:zh":"hamburger","grammar:5484:ex2:words:2:note":"loanword","grammar:5484:ex2:words:2:pos":"noun","grammar:5484:ex2:words:3:zh":"(object marker)","grammar:5484:ex2:words:3:pos":"particle","grammar:5484:ex2:words:4:zh":"ate","grammar:5484:ex2:words:4:note":"たべました","grammar:5484:ex2:words:4:pos":"verb","grammar:5484:ex2:points:0":"〜に: at … (a point in time; 昼ごはんに = at lunch)","grammar:5484:ex2:points:1":"ハンバーガー: hamburger","grammar:5484:ex3:trans":"The hamburger is one kind of fast food.","grammar:5484:ex3:structure":"名詞は＋〔ファーストフードの一つ〕＋です. 「〜の一つ」 = one of …","grammar:5484:ex3:words:0:zh":"hamburger","grammar:5484:ex3:words:0:note":"loanword","grammar:5484:ex3:words:0:pos":"noun","grammar:5484:ex3:words:1:zh":"(topic marker)","grammar:5484:ex3:words:1:pos":"particle","grammar:5484:ex3:words:2:zh":"fast food","grammar:5484:ex3:words:2:note":"loanword: fast food","grammar:5484:ex3:words:2:pos":"noun","grammar:5484:ex3:words:3:zh":"'s","grammar:5484:ex3:words:3:pos":"particle","grammar:5484:ex3:words:4:zh":"one","grammar:5484:ex3:words:4:note":"ひとつ","grammar:5484:ex3:words:4:pos":"noun","grammar:5484:ex3:words:5:zh":"is","grammar:5484:ex3:words:5:pos":"copula","grammar:5484:ex3:points:0":"〜の一つ: one of …","grammar:5484:ex3:points:1":"ファーストフード: fast food","grammar:5484:ex4:trans":"I ordered a hamburger.","grammar:5484:ex4:structure":"名詞を＋注文しました. 「注文する」 = to order (food).","grammar:5484:ex4:words:0:zh":"hamburger","grammar:5484:ex4:words:0:note":"loanword","grammar:5484:ex4:words:0:pos":"noun","grammar:5484:ex4:words:1:zh":"(object marker)","grammar:5484:ex4:words:1:pos":"particle","grammar:5484:ex4:words:2:zh":"ordered","grammar:5484:ex4:words:2:note":"ちゅうもんしました","grammar:5484:ex4:words:2:pos":"verb","grammar:5484:ex4:points:0":"注文する: to order","grammar:5484:ex4:points:1":"ハンバーガー: hamburger","grammar:5484:ex5:trans":"I ate hamburgers with a friend.","grammar:5484:ex5:structure":"名詞と＋一緒に＋名詞を＋食べました。","grammar:5484:ex5:words:0:zh":"friend","grammar:5484:ex5:words:0:note":"ともだち","grammar:5484:ex5:words:0:pos":"noun","grammar:5484:ex5:words:1:zh":"with","grammar:5484:ex5:words:1:pos":"particle","grammar:5484:ex5:words:2:zh":"together","grammar:5484:ex5:words:2:note":"いっしょに","grammar:5484:ex5:words:2:pos":"adverb","grammar:5484:ex5:words:3:zh":"hamburger","grammar:5484:ex5:words:3:note":"loanword","grammar:5484:ex5:words:3:pos":"noun","grammar:5484:ex5:words:4:zh":"(object marker)","grammar:5484:ex5:words:4:pos":"particle","grammar:5484:ex5:words:5:zh":"ate","grammar:5484:ex5:words:5:note":"たべました","grammar:5484:ex5:words:5:pos":"verb","grammar:5484:ex5:points:0":"〜と一緒に: together with…","grammar:5484:ex5:points:1":"ハンバーガーを食べる: eat a hamburger"},"5485":{"example:5485:exzh":"I stayed up late last night.","example:5485:exzh2":"Last night's party was fun.","example:5485:exzh3":"Did you watch last night's news?","example:5485:exzh4":"What was dinner last night?","example:5485:exzh5":"The stars looked beautiful last night."},"5486":{"example:5486:exzh":"It's important to keep it in its original state.","example:5486:exzh2":"Life was harsh for people in primitive times.","example:5486:exzh3":"I went to a primeval forest with a friend.","example:5486:exzh4":"Learning about primitive culture is interesting.","example:5486:exzh5":"I felt the beauty of the primitive."},"5487":{"example:5487:exzh":"I like fried eggs.","example:5487:exzh3":"Your eyeballs are so beautiful, aren't they?","example:5487:exzh4":"Something got into my eyeball.","example:5487:exzh5":"I feel that my eyeballs are tired."},"5488":{"example:5488:exzh":"We must solve this problem.","example:5488:exzh2":"Our team is strong.","example:5488:exzh3":"We must adapt.","example:5488:exzh4":"We work together.","example:5488:exzh5":"We achieved our goal."},"5489":{"example:5489:exzh":"I work together with colleagues who joined the same year.","example:5489:exzh2":"I went out for drinks with a friend who joined the same year.","example:5489:exzh3":"I had the best results among my cohort.","example:5489:exzh4":"He is the only man in the cohort.","example:5489:exzh5":"I value the bonds with my cohort."},"5490":{"example:5490:exzh":"The government granted pardons to certain criminals.","example:5490:exzh2":"The people covered by the pardon have been announced.","example:5490:exzh3":"A pardon is part of the legal process.","example:5490:exzh4":"Because he received a pardon, he was released right away.","example:5490:exzh5":"A pardon is applied in special cases."},"5491":{"example:5491:exzh":"His son is attending university.","example:5491:exzh2":"Raising a son is a difficult thing.","example:5491:exzh3":"She has two sons.","example:5491:exzh4":"I'm putting effort into my son's education.","example:5491:exzh5":"His son is good at sports."},"5492":{"example:5492:exzh":"He is a very patriotic person.","example:5492:exzh2":"Many citizens have a strong sense of patriotism.","example:5492:exzh3":"Patriotic action is being called for.","example:5492:exzh4":"The spirit of patriotism is expressed in her poetry.","example:5492:exzh5":"Patriotism is an important value."},"5493":{"example:5493:exzh":"The balloon popped.","example:5493:exzh2":"He looks like he's about to burst with joy.","example:5493:exzh3":"I threw a water balloon and made it pop.","example:5493:exzh4":"The emotions burst out.","example:5493:exzh5":"The candy burst in the mouth."},"5494":{"example:5494:exzh":"Space is required for storing food supplies.","example:5494:exzh2":"He made a special place for storage.","example:5494:exzh3":"Storage should be done according to a plan.","example:5494:exzh4":"The storeroom is old and unusable.","example:5494:exzh5":"The stored food won't go to waste."},"5495":{"example:5495:exzh":"That bastard tricked me!","example:5495:exzh2":"I get angry when someone calls me a bastard.","example:5495:exzh3":"Sometimes that bastard gets on my nerves.","example:5495:exzh4":"You're just a bastard!","example:5495:exzh5":"I really think he's a bastard."},"5496":{"example:5496:exzh":"His prison sentence is 10 years.","example:5496:exzh2":"He got out of prison after a short sentence.","example:5496:exzh3":"Once the prison term ends, you're free.","example:5496:exzh4":"There's a procedure for shortening a prison sentence.","example:5496:exzh5":"He is serving his prison sentence."},"5497":{"example:5497:exzh":"I left something behind at the station.","grammar:5497:ex:trans":"I left something behind at the station.","grammar:5497:ex:structure":"場所で＋名詞を＋しました. 「忘れ物をする」 = to forget something, to leave something behind. 「で」 marks the place of the action.","grammar:5497:ex:explain":"This sentence uses 「〜で〜をする」, with 「で」 marking where the action happens. In 「駅で」, 「で」 marks the place where the action takes place: at the station. 「忘れ物をする」 is an idiom whose literal shape is to do a forgotten thing, but which actually means to forget or leave something behind by mistake. 「しました」 is the polite past. The whole sentence means I left something behind at the station. Note that 「で」 marks the place of an action, unlike 「に」, which marks existence.","grammar:5497:ex:words:0:zh":"station","grammar:5497:ex:words:0:note":"えき","grammar:5497:ex:words:0:pos":"noun","grammar:5497:ex:words:1:zh":"(place of the action)","grammar:5497:ex:words:1:pos":"particle","grammar:5497:ex:words:2:zh":"lost property","grammar:5497:ex:words:2:note":"わすれもの","grammar:5497:ex:words:2:pos":"noun","grammar:5497:ex:words:3:zh":"(object marker)","grammar:5497:ex:words:3:pos":"particle","grammar:5497:ex:words:4:zh":"did","grammar:5497:ex:words:4:note":"忘れ物をする = to lose something / leave something behind","grammar:5497:ex:words:4:pos":"verb","grammar:5497:ex:points:0":"忘れ物をする: to forget, to leave something behind","grammar:5497:ex:points:1":"で: place of action (駅で = at the station)"},"5498":{"example:5498:exzh":"An event will be held next week."},"5499":{"example:5499:exzh":"I want to witness his success."}};